// FR-01, FR-02, FR-32 | UML: StudentAccount, MerchantAccount, AdministratorAccount;
// UC_Register, UC_Login, UC_Merchants, UC_Admins;
// sequence-order registration/sign-in, sequence-catalog sign-in, sequence-admin account management.
import { Body, Controller, Injectable, NotImplementedException, Param, Patch, Post } from '@nestjs/common';

interface StudentSignIn {
  studentNumber: string;
  password: <SECRET>
}

interface StudentRegistration extends StudentSignIn {
  nickname: string;
}

interface MerchantBasicInformation {
  name: string;
  // G3-06: additional basic-information fields are Unconfirmed.
}

interface CreatedMerchantAccount {
  merchantId: string;
  accountCredentials: { account: string; password: <SECRET> };
}

interface MerchantAccountState {
  merchantId: string;
  name: string;
  active: boolean;
}

@Injectable()
export class AccountsService {
  registerStudent(_registration: StudentRegistration): { studentAccountId: string } {
    throw new NotImplementedException();
  }

  signInStudent(_credentials: StudentSignIn): { role: 'student' } {
    throw new NotImplementedException();
  }

  signInMerchant(_credentials: CreatedMerchantAccount['accountCredentials']): { role: 'merchant' } {
    throw new NotImplementedException();
  }

  signInAdministrator(_credentials: unknown): { role: 'administrator' } {
    throw new NotImplementedException();
  }
}

@Controller('accounts')
export class AccountsController {
  constructor(private readonly accounts: AccountsService) {}

  @Post('students')
  registerStudent(@Body() registration: StudentRegistration) {
    return this.accounts.registerStudent(registration);
  }

  @Post('students/sign-in')
  signInStudent(@Body() credentials: StudentSignIn) {
    return this.accounts.signInStudent(credentials);
  }

  @Post('merchants/sign-in')
  signInMerchant(@Body() credentials: CreatedMerchantAccount['accountCredentials']) {
    return this.accounts.signInMerchant(credentials);
  }

  @Post('administrators/sign-in')
  signInAdministrator(@Body() credentials: unknown) {
    return this.accounts.signInAdministrator(credentials);
  }
}

@Injectable()
export class AdministrationService {
  createMerchant(_information: MerchantBasicInformation): CreatedMerchantAccount {
    throw new NotImplementedException();
  }

  updateMerchant(_merchantId: string, _information: MerchantBasicInformation): MerchantAccountState {
    throw new NotImplementedException();
  }

  deactivateMerchant(_merchantId: string): MerchantAccountState {
    throw new NotImplementedException();
  }

  createAdministrator(_accountDetails: unknown): { administratorAccountId: string } {
    throw new NotImplementedException();
  }
}

@Controller('administration')
export class AdministrationController {
  constructor(private readonly administration: AdministrationService) {}

  @Post('merchants')
  createMerchant(@Body() information: MerchantBasicInformation) {
    return this.administration.createMerchant(information);
  }

  @Patch('merchants/:merchantId')
  updateMerchant(@Param('merchantId') merchantId: string, @Body() information: MerchantBasicInformation) {
    return this.administration.updateMerchant(merchantId, information);
  }

  @Patch('merchants/:merchantId/deactivate')
  deactivateMerchant(@Param('merchantId') merchantId: string) {
    return this.administration.deactivateMerchant(merchantId);
  }

  @Post('administrators')
  createAdministrator(@Body() accountDetails: unknown) {
    return this.administration.createAdministrator(accountDetails);
  }
}
// FR-01, FR-06, FR-10, FR-11, FR-12, FR-13, FR-14, FR-15, FR-16, FR-17, FR-18,
// FR-19, FR-20, FR-21, FR-22, FR-23, FR-24, FR-25, FR-27, FR-28, FR-31
// UML: Cart, CartLine, Order and Suborder; UC_Cart and UC_Submit;
// sequence-order Cart, Order Service and Inventory; activity-order.
import { Body, Controller, Delete, Get, Injectable, NotImplementedException, Param, Post, Put } from '@nestjs/common';

interface CartLineSelection {
  quantity: number;
  selectedOptionIds: string[];
  note?: string;
}

export interface CartLine extends CartLineSelection {
  cartLineId: string;
  itemId: string;
}

// FR-15: the cart contract leaves its persistence and sign-in handoff open.
export interface Cart {
  lines: CartLine[];
}

interface LineAmount {
  baseUnitPrice: number;
  addOnAmount: number;
  subtotal: number;
}

interface AmountBreakdown {
  merchantAmounts: {
    merchantId: string;
    lines: ({ cartLineId: string } & LineAmount)[];
    subtotal: number;
    effectiveDiscount: number;
    total: number;
  }[];
  orderTotal: number;
}

interface CartContents extends Cart {
  amounts: AmountBreakdown;
}

interface SubmitOrder {
  confirmationId: string;
  pickupTimes: { merchantId: string; pickupTime: string }[];
  confirmedAmounts: AmountBreakdown;
}

type SubmissionFailure = { outcome: 'failed'; reason: string };
type AmountChange = { outcome: 'requires_confirmation'; amounts: AmountBreakdown };

type FirstSubmissionResult = { outcome: 'submitted'; orderId: string } | SubmissionFailure;
type SubmissionResult = FirstSubmissionResult | AmountChange;

interface StockQuantity {
  itemId: string;
  quantity: number;
}

// FR-10, FR-22, FR-24, FR-27 | UML: Inventory in sequence-order and sequence-suborders.
export interface Inventory {
  checkAvailability(lines: readonly CartLine[]): Promise<{ available: boolean }>;
  deductQuantityModeStock(quantities: readonly StockQuantity[]): Promise<void>;
  restoreEligibleQuantityModeStock(suborderId: string): Promise<void>;
}

// FR-17, FR-22–FR-25 | UML: Merchant Catalog revalidation and Order Service in sequence-order.
export interface OrderSubmissionOperations {
  revalidate(cart: Cart, confirmation: SubmitOrder): Promise<{ outcome: 'valid' } | SubmissionFailure | AmountChange>;
  createOrderAndDeductStock(
    studentAccountId: string,
    cart: Cart,
    confirmation: SubmitOrder,
  ): Promise<FirstSubmissionResult>;
  findResultForConfirmation(studentAccountId: string, confirmationId: string): Promise<FirstSubmissionResult | null>;
}

@Injectable()
export class CartService {
  getCart(): CartContents {
    throw new NotImplementedException();
  }

  addLine(_line: Omit<CartLine, 'cartLineId'>): CartContents {
    throw new NotImplementedException();
  }

  editLine(_cartLineId: string, _selection: CartLineSelection): CartContents {
    throw new NotImplementedException();
  }

  removeLine(_cartLineId: string): CartContents {
    throw new NotImplementedException();
  }

  clearAfterSubmission(): void {
    throw new NotImplementedException();
  }
}

@Controller('cart')
export class CartController {
  constructor(private readonly cart: CartService) {}

  @Get()
  getCart() {
    return this.cart.getCart();
  }

  @Post('lines')
  addLine(@Body() line: Omit<CartLine, 'cartLineId'>) {
    return this.cart.addLine(line);
  }

  @Put('lines/:cartLineId')
  editLine(@Param('cartLineId') cartLineId: string, @Body() selection: CartLineSelection) {
    return this.cart.editLine(cartLineId, selection);
  }

  @Delete('lines/:cartLineId')
  removeLine(@Param('cartLineId') cartLineId: string) {
    return this.cart.removeLine(cartLineId);
  }
}

@Injectable()
export class OrderSubmissionService {
  // FR-24, FR-25: student identity comes from the session; retry uses the same confirmation ID.
  submit(_confirmation: SubmitOrder): SubmissionResult {
    throw new NotImplementedException();
  }
}

@Controller('student/orders')
export class OrderSubmissionController {
  constructor(private readonly orders: OrderSubmissionService) {}

  @Post()
  submit(@Body() confirmation: SubmitOrder) {
    return this.orders.submit(confirmation);
  }
}
// FR-02, FR-13, FR-17, FR-18, FR-19, FR-21, FR-26, FR-27, FR-28, FR-29, FR-30, FR-31, FR-33
// UML: Order, Suborder, OrderLine, SelectedOption; UC_ViewOrder, UC_Suborders;
// sequence-suborders merchant handling and student/merchant query.
import { Body, Controller, Get, Injectable, NotImplementedException, Param, Patch } from '@nestjs/common';

type SuborderStatus = 'PENDING' | 'ACCEPTED' | 'READY' | 'PICKED_UP' | 'REJECTED';
type AggregateStatus = 'SUBMITTED' | 'IN_PREPARATION' | 'COMPLETE' | 'PICKED_UP' | 'REJECTED';
type SuborderStatusGroups = Partial<Record<SuborderStatus, string[]>>;

interface VisibleSuborder {
  suborderId: string;
  merchant: { merchantId: string; name: string };
  status: SuborderStatus;
  pickupTime: string;
  discount: number;
  total: number;
  lines: {
    itemNameSnapshot: string;
    basePriceSnapshot: number;
    quantity: number;
    note: string | null;
    selectedOptions: { optionNameSnapshot: string; surchargeSnapshot: number }[];
    addOnAmount: number;
    subtotal: number;
  }[];
}

interface MerchantOrderDetails {
  orderId: string;
  suborders: VisibleSuborder[];
  suborderIdsByStatus: SuborderStatusGroups;
}

interface StudentOrderDetails extends MerchantOrderDetails {
  total: number;
  aggregateStatus: AggregateStatus;
}

// FR-33 | UML: Order.aggregateStatus and the sequence-suborders status derivation.
export interface AggregateOrderStatus {
  derive(statuses: readonly SuborderStatus[]): AggregateStatus;
}

@Injectable()
export class SuborderService {
  findMerchantSuborders(): { orderId: string; suborder: VisibleSuborder }[] {
    throw new NotImplementedException();
  }

  updateStatus(_suborderId: string, _status: SuborderStatus): { suborderId: string; status: SuborderStatus } {
    throw new NotImplementedException();
  }

  findStudentOrders(): { orderId: string }[] {
    throw new NotImplementedException();
  }

  readStudentOrder(_orderId: string): StudentOrderDetails {
    throw new NotImplementedException();
  }

  readMerchantOrder(_orderId: string): MerchantOrderDetails {
    throw new NotImplementedException();
  }
}

@Controller('student/orders')
export class OrderQueryController {
  constructor(private readonly suborders: SuborderService) {}

  @Get()
  findStudentOrders() {
    return this.suborders.findStudentOrders();
  }

  @Get(':orderId')
  readStudentOrder(@Param('orderId') orderId: string) {
    return this.suborders.readStudentOrder(orderId);
  }
}

@Controller('merchant')
export class SuborderController {
  constructor(private readonly suborders: SuborderService) {}

  @Get('suborders')
  findOwnSuborders() {
    return this.suborders.findMerchantSuborders();
  }

  @Patch('suborders/:suborderId/status')
  updateStatus(@Param('suborderId') suborderId: string, @Body('status') status: SuborderStatus) {
    return this.suborders.updateStatus(suborderId, status);
  }

  @Get('orders/:orderId')
  readOwnOrder(@Param('orderId') orderId: string) {
    return this.suborders.readMerchantOrder(orderId);
  }
}
// FR-03, FR-04, FR-05, FR-06, FR-07, FR-08, FR-09, FR-10, FR-11, FR-18, FR-20, FR-28
// UML: Merchant, Category, Item, OptionGroup, CustomOption; UC_Browse, UC_Search, UC_Catalog,
// UC_Discount; Merchant Catalog in sequence-order; Catalog in sequence-catalog.
import { Body, Controller, Delete, Get, Injectable, NotImplementedException, Param, Patch, Post, Put, Query } from '@nestjs/common';

