    if isinstance(value, dict):
        for key, child in value.items():
            if key in AMOUNT_KEYS:
                assert type(child) is int and child >= 0, key
            elif key == "status":
                assert child in SUBORDER_STATUSES, child
            elif key == "aggregateStatus":
                assert allow_aggregate, key
            check_values(child, allow_aggregate=allow_aggregate)
    elif isinstance(value, list):
        for child in value:
            check_values(child, allow_aggregate=allow_aggregate)

def check_suborder(suborder):
    subtotal = 0
    datetime.fromisoformat(suborder["pickupTime"])
    assert suborder["lines"], suborder
    for line in suborder["lines"]:
        assert 1 <= line["quantity"] <= 99, line
        add_ons = sum(option["surchargeSnapshot"] for option in line["selectedOptions"])
        assert line["addOnAmount"] == add_ons * line["quantity"], line
        assert line["subtotal"] == line["basePriceSnapshot"] * line["quantity"] + line["addOnAmount"], line
        subtotal += line["subtotal"]
    assert suborder["total"] == subtotal - suborder["discount"], suborder

def check_order(order, *, student):
    assert order["suborders"], order
    groups = defaultdict(list)
    for suborder in order["suborders"]:
        check_suborder(suborder)
        groups[suborder["status"]].append(suborder["suborderId"])
    assert dict(groups) == order["suborderIdsByStatus"], order
    if student:
        statuses = set(groups) - {"REJECTED"}
        if not statuses:
            expected = "REJECTED"
        elif statuses == {"PENDING"}:
            expected = "SUBMITTED"
        elif "ACCEPTED" in statuses or "PENDING" in statuses:
            expected = "IN_PREPARATION"
        elif "READY" in statuses:
            expected = "COMPLETE"
        else:
            expected = "PICKED_UP"
        assert order["aggregateStatus"] == expected, order
        assert order["total"] == sum(suborder["total"] for suborder in order["suborders"]), order
    else:
